B.Xx=new A.ch("Tu \u0438\u043b\u0438 vous?","\u0421 \u0434\u0440\u0443\u0437\u044c\u044f\u043c\u0438 \u0438 \u0434\u0435\u0442\u044c\u043c\u0438 \u2014 tu, \u0441 \u043d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u044b\u043c\u0438 \u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u043c\u0438 \u2014 vous. \u041f\u0435\u0440\u0435\u0439\u0442\u0438 \u043d\u0430 \xab\u0442\u044b\xbb \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u0442\u043e\u0442, \u043a\u0442\u043e \u0441\u0442\u0430\u0440\u0448\u0435 \u0438\u043b\u0438 \u0433\u043b\u0430\u0432\u043d\u0435\u0435.",!0)
B.Xl=new A.ch("Le \u0438 la","\u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u0432\u043e\u0439 \u0440\u043e\u0434, \u0438 \u043e\u043d \u0447\u0430\u0441\u0442\u043e \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0435\u0442 \u0441 \u0440\u0443\u0441\u0441\u043a\u0438\u043c: la table \u2014 \u0436\u0435\u043d\u0441\u043a\u043e\u0433\u043e, le lit \u2014 \u043c\u0443\u0436\u0441\u043a\u043e\u0433\u043e. \u0423\u0447\u0438\u0442\u0435 \u0441\u043b\u043e\u0432\u043e \u0441\u0440\u0430\u0437\u0443 \u0441 \u0430\u0440\u0442\u0438\u043a\u043b\u0435\u043c.",!0)
B.Xk=new A.ch("\u0410\u043f\u043e\u0441\u0442\u0440\u043e\u0444","Le \u0438 la \u043f\u0435\u0440\u0435\u0434 \u0433\u043b\u0430\u0441\u043d\u043e\u0439 \u0442\u0435\u0440\u044f\u044e\u0442 \u0431\u0443\u043a\u0432\u0443: l\u2019ami, l\u2019\xe9cole. \u0422\u0430\u043a \u0436\u0435 je \u2192 j\u2019ai, ne \u2192 n\u2019est.",!0)
B.Xs=new A.ch("Accent aigu \u0438 grave","\xe9 \u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0437\u0430\u043a\u0440\u044b\u0442\u043e, \u043a\u0430\u043a \xab\u044d\xbb \u0432 \xab\u044d\u0442\u0438\xbb; \xe8 \u0438 \xea \u2014 \u043e\u0442\u043a\u0440\u044b\u0442\u043e. \u0417\u043d\u0430\u043a \u043d\u0430\u0434 a \u0438 u \u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u043c\u044b\u0441\u043b: a \u2014 \xab\u0438\u043c\u0435\u0435\u0442\xbb, \xe0 \u2014 \xab\u0432\xbb; ou \u2014 \xab\u0438\u043b\u0438\xbb, o\xf9 \u2014 \xab\u0433\u0434\u0435\xbb.",!0)
